class LFUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.values = {}
        self.freq = defaultdict(OrderedDict)
        self.count = {}
        self.min_freq = 0

    def get(self, key):
        if key not in self.values:
            return -1
        self._touch(key)
        return self.values[key]

    def _touch(self, key):
        f = self.count[key]
        del self.freq[f][key]
        if not self.freq[f]:
            del self.freq[f]
            if self.min_freq == f:
                self.min_freq += 1
        self.count[key] = f + 1
        self.freq[f + 1][key] = None

    def put(self, key, value):
        if self.capacity == 0:
            return
        if key in self.values:
            self.values[key] = value
            self._touch(key)
            return
        if len(self.values) == self.capacity:
            old = next(iter(self.freq[self.min_freq]))
            del self.freq[self.min_freq][old]
            del self.values[old]
            del self.count[old]
        self.values[key] = value
        self.count[key] = 1
        self.freq[1][key] = None
        self.min_freq = 1

class LFUCache {
    int cap, minFreq;
    unordered_map<int, pair<int,int>> data;
    unordered_map<int, list<int>> freqList;
    unordered_map<int, list<int>::iterator> pos;
public:
    LFUCache(int capacity) : cap(capacity), minFreq(0) {}

    int get(int key) {
        if (!data.count(key)) return -1;
        int value = data[key].first;
        update(key);
        return value;
    }

    void update(int key) {
        int f = data[key].second;
        freqList[f].erase(pos[key]);
        if (freqList[f].empty() && minFreq == f) minFreq++;
        data[key].second++;
        freqList[f + 1].push_back(key);
        pos[key] = prev(freqList[f + 1].end());
    }

    void put(int key, int value) {
        if (cap == 0) return;
        if (data.count(key)) {
            data[key].first = value;
            update(key);
            return;
        }
        if (data.size() == cap) {
            int old = freqList[minFreq].front();
            freqList[minFreq].pop_front();
            data.erase(old);
            pos.erase(old);
        }
        data[key] = {value, 1};
        freqList[1].push_back(key);
        pos[key] = prev(freqList[1].end());
        minFreq = 1;
    }
};

class LFUCache {
    private final int capacity;
    private final Map<Integer,Integer> values = new HashMap<>();
    private final Map<Integer,Integer> count = new HashMap<>();

    LFUCache(int capacity) {
        this.capacity = capacity;
    }

    public int get(int key) {
        if (!values.containsKey(key)) return -1;
        count.put(key, count.get(key) + 1);
        return values.get(key);
    }

    public void put(int key, int value) {
        if (capacity == 0) return;
        if (values.containsKey(key)) {
            values.put(key, value);
            count.put(key, count.get(key) + 1);
            return;
        }
        if (values.size() == capacity) {
            int victim = Collections.min(count.entrySet(),
                Comparator.comparingInt(Map.Entry::getValue)).getKey();
            values.remove(victim);
            count.remove(victim);
        }
        values.put(key, value);
        count.put(key, 1);
    }
}

