class Fenwick:
    def __init__(self, n):
        self.bit = [0] * (n + 1)

    def add(self, i, delta):
        i += 1
        while i < len(self.bit):
            self.bit[i] += delta
            i += i & -i

    def sum(self, i):
        ans = 0
        i += 1
        while i:
            ans += self.bit[i]
            i -= i & -i
        return ans

    def range_sum(self, l, r):
        return self.sum(r) - (self.sum(l - 1) if l else 0)

