class SegmentTree:
    def __init__(self, nums):
        self.n = len(nums)
        self.tree = [0] * (4 * self.n)
        self.build(nums, 1, 0, self.n - 1)

    def build(self, a, node, l, r):
        if l == r:
            self.tree[node] = a[l]
            return
        m = (l + r) // 2
        self.build(a, node*2, l, m)
        self.build(a, node*2+1, m+1, r)
        self.tree[node] = self.tree[node*2] + self.tree[node*2+1]

    def query(self, node, l, r, ql, qr):
        if qr < l or r < ql:
            return 0
        if ql <= l and r <= qr:
            return self.tree[node]
        m = (l+r)//2
        return self.query(node*2,l,m,ql,qr) + self.query(node*2+1,m+1,r,ql,qr)

