class RangeModule:
    def __init__(self):
        self.ranges = []

    def addRange(self, left, right):
        self.ranges.append((left, right))
        self.ranges.sort()
        merged = []
        for l, r in self.ranges:
            if not merged or l > merged[-1][1]:
                merged.append([l,r])
            else:
                merged[-1][1] = max(merged[-1][1], r)
        self.ranges = [tuple(x) for x in merged]

    def queryRange(self, left, right):
        return any(l <= left and right <= r for l,r in self.ranges)

class RangeModule {
    map<int,int> ranges;
public:
    void addRange(int left, int right) {
        auto it = ranges.lower_bound(left);
        if (it != ranges.begin() && prev(it)->second >= left) --it;
        while (it != ranges.end() && it->first <= right) {
            left = min(left, it->first);
            right = max(right, it->second);
            it = ranges.erase(it);
        }
        ranges[left] = right;
    }

    bool queryRange(int left, int right) {
        auto it = ranges.upper_bound(left);
        if (it == ranges.begin()) return false;
        --it;
        return it->second >= right;
    }
};

class RangeModule {
    TreeMap<Integer,Integer> map = new TreeMap<>();

    public void addRange(int left, int right) {
        Integer start = map.floorKey(left);
        if (start != null && map.get(start) >= left) {
            left = start;
            right = Math.max(right, map.get(start));
            map.remove(start);
        }
        while (true) {
            Integer next = map.ceilingKey(left);
            if (next == null || next > right) break;
            right = Math.max(right, map.get(next));
            map.remove(next);
        }
        map.put(left, right);
    }

    public boolean queryRange(int left, int right) {
        Integer start = map.floorKey(left);
        return start != null && map.get(start) >= right;
    }
}

